//! Q26/Q28/C18, the ladder, optional EMPHASIS and both VCAs through J7.
//! All control sources are imposed electrical boundaries, not a complete voice.

use crate::cutoff;
use crate::ladder_recovery_output::{self as chain, CutoffContext, StepResult};
use crate::output_conversion::Parameters as ConversionParameters;
use crate::recovery_vca_output::Boundary as RecoveryBoundary;
use crate::vca2_output::Parameters as TransistorParameters;
use crate::{Parameters as HeadphoneParameters, SolverBudget, StepError};

#[derive(Clone, Copy, Debug)]
pub struct Parameters {
    pub ladder_transistor: TransistorParameters,
    pub cutoff: cutoff::Parameters,
    pub r61_ohm: f64,
    pub r30_ohm: f64,
}

#[derive(Clone, Copy, Debug)]
pub struct Boundary {
    pub bus_v: f64,
    pub recovery: RecoveryBoundary,
    pub panel: cutoff::PanelBoundary,
    pub range_fraction_from_ground: f64,
    /// None opens the laboratory C10 return; Some closes its series resistance.
    pub r14_ohm: Option<f64>,
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct State {
    pub chain: chain::State,
    pub cutoff: cutoff::State,
}

fn inputs(
    p: Parameters,
    b: Boundary,
    previous: cutoff::State,
) -> Result<
    (
        chain::Parameters,
        chain::Boundary,
        CutoffContext,
        Option<f64>,
    ),
    StepError,
> {
    let lp = chain::Parameters {
        transistor: p.ladder_transistor,
        // Internal fixed-current stamp is replaced by the nonlinear TAIL port
        // on every residual evaluation; this value is not an electrical input.
        tail_current_a: 1e-6,
        r61_ohm: p.r61_ohm,
        r30_ohm: p.r30_ohm,
    };
    let lb = chain::Boundary {
        bus_v: b.bus_v,
        recovery: b.recovery,
    };
    let context = CutoffContext {
        previous,
        parameters: p.cutoff,
        boundary: cutoff::Boundary {
            panel: b.panel,
            range_fraction_from_ground: b.range_fraction_from_ground,
            tail_v: 0.0, // Replaced by the outer trial's TAIL voltage.
            dt_s: b.recovery.vca.second.output.output.dt_s,
        },
    };
    let series = b
        .r14_ohm
        .map(|v| chain::return_series_ohm(lp, v))
        .transpose()?;
    Ok((lp, lb, context, series))
}

/// Solve Q26/Q28 and all sixteen ladder nodes jointly at DC. Coupling
/// capacitors are open; their charges are initialized at the converged point.
pub fn initial_state(
    p: Parameters,
    conversion: ConversionParameters,
    headphone: HeadphoneParameters,
    b: Boundary,
    ladder_seed: [f64; 16],
) -> Result<State, StepError> {
    let dummy = cutoff::State {
        node_v: [0.0; 4],
        c18_v: 0.0,
    };
    let (lp, lb, context, _) = inputs(p, b, dummy)?;
    let (chain, cutoff) =
        chain::initial_state_internal(lp, conversion, headphone, lb, ladder_seed, Some(context))?;
    Ok(State {
        chain,
        cutoff: cutoff.expect("connected cutoff port"),
    })
}

/// Same C18/capacitor history on every trial, including predictor fallback.
/// No state is published until the entire nested circuit converges.
pub fn step(
    state: &mut State,
    p: Parameters,
    conversion: ConversionParameters,
    headphone: HeadphoneParameters,
    b: Boundary,
    budget: SolverBudget,
) -> Result<StepResult, StepError> {
    let (lp, lb, context, series) = inputs(p, b, state.cutoff)?;
    let (result, cutoff) = chain::step_internal(
        &mut state.chain,
        lp,
        conversion,
        headphone,
        lb,
        budget,
        series,
        Some(context),
    )?;
    state.cutoff = cutoff.expect("connected cutoff port");
    Ok(result)
}

//! Conditional depletion charge, NG-46 pp.138-145/152-154. SI units.
//! Fixed previous junction voltage during Newton; no state publication.
#[derive(Clone, Copy, Debug)]
pub struct Parameters {
    pub zero_bias_capacitance_f: f64,
    pub potential_v: f64,
    pub grading: f64,
    pub forward_fraction: f64,
}

#[derive(Clone, Copy, Debug)]
pub struct Charge {
    pub charge_c: f64,
    pub capacitance_f: f64,
}

#[derive(Clone, Copy, Debug)]
pub struct Companion {
    pub next_charge_c: f64,
    pub capacitance_f: f64,
    pub delta_charge_c: f64,
    pub current_a: f64,
    pub conductance_s: f64,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Error { InvalidInput, NonFiniteResult }

impl Parameters {
    fn validate(self, v: f64) -> Result<(), Error> {
        if !v.is_finite() || !(-40.0..=40.0).contains(&v)
            || !self.zero_bias_capacitance_f.is_finite() || self.zero_bias_capacitance_f < 0.0
            || !self.potential_v.is_finite() || self.potential_v <= 0.0
            || !self.grading.is_finite() || !(0.0..1.0).contains(&self.grading)
            || !self.forward_fraction.is_finite() || !(0.0..=0.95).contains(&self.forward_fraction)
        { return Err(Error::InvalidInput); }
        Ok(())
    }

    fn splice(self) -> (f64, f64, f64) {
        let v = self.forward_fraction*self.potential_v;
        let c = self.zero_bias_capacitance_f*(1.0-self.forward_fraction).powf(-self.grading);
        let slope = c*self.grading/(self.potential_v*(1.0-self.forward_fraction));
        (v, c, slope)
    }

    fn low_charge(self, v: f64) -> f64 {
        let exponent = 1.0-self.grading;
        -self.zero_bias_capacitance_f*self.potential_v/exponent
            * (exponent*(-v/self.potential_v).ln_1p()).exp_m1()
    }

    pub fn charge(self, v: f64) -> Result<Charge, Error> {
        self.validate(v)?;
        if self.zero_bias_capacitance_f == 0.0 {
            return Ok(Charge { charge_c: 0.0, capacitance_f: 0.0 });
        }
        let (vf, cf, slope) = self.splice();
        let result = if v < vf {
            Charge { charge_c: self.low_charge(v),
                capacitance_f: self.zero_bias_capacitance_f
                    * (-self.grading*(-v/self.potential_v).ln_1p()).exp() }
        } else {
            let delta = v-vf;
            Charge { charge_c: self.low_charge(vf)+delta*(cf+0.5*slope*delta),
                     capacitance_f: cf+slope*delta }
        };
        if !result.charge_c.is_finite() || !result.capacitance_f.is_finite() {
            return Err(Error::NonFiniteResult);
        }
        Ok(result)
    }

    fn low_increment(self, from: f64, to: f64) -> f64 {
        let exponent = 1.0-self.grading;
        let factor = (-from/self.potential_v).ln_1p();
        let relative = (-(to-from)/(self.potential_v-from)).ln_1p();
        -self.zero_bias_capacitance_f*self.potential_v/exponent
            * (exponent*factor).exp() * (exponent*relative).exp_m1()
    }

    fn high_increment(self, from: f64, to: f64) -> f64 {
        let (vf, cf, slope) = self.splice();
        (to-from)*(cf+slope*(from-vf)+0.5*slope*(to-from))
    }

    /// Exact piecewise integral of C(v), evaluated without Q(to)-Q(from).
    pub fn charge_increment(self, from: f64, to: f64) -> Result<f64, Error> {
        self.validate(from)?; self.validate(to)?;
        // Also validate the charge domain and derived coefficients.
        self.charge(from)?; self.charge(to)?;
        if from == to || self.zero_bias_capacitance_f == 0.0 { return Ok(0.0); }
        let (lo, hi, sign) = if to > from { (from, to, 1.0) } else { (to, from, -1.0) };
        let (vf, _, _) = self.splice();
        let value = sign*if hi <= vf { self.low_increment(lo, hi) }
            else if lo >= vf { self.high_increment(lo, hi) }
            else { self.low_increment(lo, vf)+self.high_increment(vf, hi) };
        if !value.is_finite() { return Err(Error::NonFiniteResult); }
        Ok(value)
    }

    /// Current enters the anode. The caller retains the same previous_v
    /// for all trials and confirms its node/charge state only after convergence.
    pub fn companion(self, v: f64, previous_v: f64, dt_s: f64) -> Result<Companion, Error> {
        if !dt_s.is_finite() || dt_s <= 0.0 { return Err(Error::InvalidInput); }
        let q = self.charge(v)?;
        let delta = self.charge_increment(previous_v, v)?;
        let current = delta/dt_s; let conductance = q.capacitance_f/dt_s;
        if !current.is_finite() || !conductance.is_finite() { return Err(Error::NonFiniteResult); }
        Ok(Companion { next_charge_c: q.charge_c, capacitance_f: q.capacitance_f,
            delta_charge_c: delta, current_a: current, conductance_s: conductance })
    }
}

