        g=F(1,8);gm=F(1,4);v98=F(1);control=F(-1);i=-gm*control
        v17=v98;v16=v17-i/g;values=(v98,v17,v16,control,F(0),i)
        row,rhs=math.stamps(F(0),F(0),g,gm)
        self.assertEqual(sum(a*b for a,b in zip(row,values)),rhs)

